import{z as B,x as A,o as e,c as p,q as s,j as l,D as E,d as t,s as o,S as n,b as i}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"掩模 3D 效应","description":"","frontmatter":{"title":"掩模 3D 效应","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-3d-effect.md","filePath":"litho/mask-3d-effect.md","lastUpdated":1791063341000}'),D={name:"litho/mask-3d-effect.md"};function h(d,a,c,m,f,C){const r=A("Mermaid");return e(),p("div",null,[a[2]||(a[2]=s('<h1 id="掩模-3d-效应" tabindex="-1">掩模 3D 效应 <a class="header-anchor" href="#掩模-3d-效应" aria-label="Permalink to &quot;掩模 3D 效应&quot;">​</a></h1><div class="epigraph"><p>吸收体有厚度，开口是波导：斜入射带来阴影，左右边不等价，最佳焦距随图形漂移，Kirchhoff 薄屏不再是零误差。</p><footer>—— 据 Mack、Levinson 对 thick-mask / EMF 效应的讨论；EUV 阴影亦见 ASML 与 Bakshi 的公开表述</footer></div><p><a href="/litho/sraf-assist">上一课</a>（亚分辨辅助图形 SRAF）。在此之上，二元与衰减掩模写成平面复透过率。缺口是：MoSi 或铬的厚度与波长同量级，光在开口里走的是电磁边值，不是乘一个 \\(t\\)。本课钉掩模三维（M3D）效应。Kirchhoff 薄屏何时失准、怎么切换到严格电磁，留给<a href="/litho/kirchhoff-vs-emf">下一课</a>；把一层拆成两次曝光去换节距，是多重图形课的事，不要在这里开始染色。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>薄屏假设下，正入射、无限薄、开口内外相位只由指定的 \\(t\\) 决定。真实掩模：吸收体厚几十纳米，侧壁不垂直，DUV 投影侧主光线已有角度，EUV 更是反射式掠入射（掩模侧典型约 \\(6^\\circ\\)）。光线被吸收体挡出一块阴影，有效开口随方位变；开口内的波导色散让 0/1 级的相位与 Kirchhoff 预测不同。</p><p>后果在晶圆上已经能看见：水平/垂直 CD 偏置（HV bias）、最佳焦距随节距和密度漂移、左右边不对称。OPC 若只用薄屏，会把这些系统误差修进错误的偏置里，换照明或换焦距就散。</p><h3 id="阴影不是套刻" tabindex="-1">阴影不是套刻 <a class="header-anchor" href="#阴影不是套刻" aria-label="Permalink to &quot;阴影不是套刻&quot;">​</a></h3><p>EUV 阴影让图形沿投影方向「看起来」平移并变窄，像套刻，根子在掩模物面。它随狭缝位置（主光线角）变，全场指纹与工件台 overlay 不同源。补偿在掩模吸收体摆放和 OPC 的 M3D 模型里，不在套刻标记的读数里消掉。</p><p><span class="marginnote">数字实例：EUV 波长约 \\(13.5\\ \\mathrm{nm}\\)，吸收体典型厚 \\(50\\)–\\(60\\ \\mathrm{nm}\\)，已经是四五个波长的厚度；DUV 波长 \\(193\\ \\mathrm{nm}\\)，铬膜也有几十纳米。所谓「薄屏」其实从不薄——厚度与波长同量级，就是 3D 效应躲不掉的原因。</span></p><p><span class="marginnote">计算上用 RCWA、FDTD 或预计算的 M3D 库给每个衍射级一个厚掩模修正。全芯片仍靠紧凑模型，不是每处现场 FDTD。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>成像链在物体频谱处把 Kirchhoff 级振幅换成电磁计算的级振幅（含偏振）。矢量成像课已经要求 Jones；本课把琼斯矩阵的来源从「薄屏」换成「厚吸收体」。校准：用不同方位的线和孔测 HV 偏置与通过焦点的 CD，把差归因到 M3D，而不是只拧剂量。</p><p><span class="marginnote">常见误区：看到水平线与垂直线宽不一样，初学者容易先怀疑剂量或显影。实际上 EUV 掩模只从一侧以约 \\(6^\\circ\\) 照明，横竖图形被吸收体投出不同宽度的阴影，HV 偏置是确定性的掩模侧效应——该修的是含 M3D 的 OPC 模型，不是工艺旋钮。</span></p><p>减厚度、换吸收体材料（EUV 上谈低 \\(n\\)、低 \\(k\\) 吸收体）是硬件方向，能减弱阴影，但检测、蚀刻选择比和缺陷是另一笔账。本课不选材料，只要求模型与膜系一致。</p><h3 id="与-ret-的叠加" tabindex="-1">与 RET 的叠加 <a class="header-anchor" href="#与-ret-的叠加" aria-label="Permalink to &quot;与 RET 的叠加&quot;">​</a></h3><p>离轴照明加大掩模侧入射角，M3D 更明显。衰减相移的膜本身就是厚的相位元件，3D 与「6% + 180°」的标称值会同时偏离。因此 att-PSM 的标称透过率是膜系设计目标，有效成像透过率要靠电磁。</p>',16)),(e(),l(n,null,{default:E(()=>[o(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20THIN%5B%22Kirchhoff%20%E8%96%84%E5%B1%8F%22%5D%20--%3E%20THICK%5B%22%E5%90%B8%E6%94%B6%E4%BD%93%E5%8E%9A%E5%BA%A6%20%2F%20%E4%BE%A7%E5%A3%81%22%5D%0A%20%20ANG%5B%22%E6%96%9C%E5%85%A5%E5%B0%84%E4%B8%BB%E5%85%89%E7%BA%BF%22%5D%20--%3E%20SHAD%5B%22%E9%98%B4%E5%BD%B1%20%2F%20%E6%9C%89%E6%95%88%E5%BC%80%E5%8F%A3%22%5D%0A%20%20THICK%20--%3E%20WG%5B%22%E5%BC%80%E5%8F%A3%E6%B3%A2%E5%AF%BC%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20SHAD%20--%3E%20HV%5B%22HV%20%E5%81%8F%E7%BD%AE%E4%B8%8E%E7%84%A6%E6%BC%82%22%5D%0A%20%20WG%20--%3E%20HV%0A%20%20HV%20--%3E%20OPC%5B%22OPC%20%E5%BF%85%E9%A1%BB%E5%90%AB%20M3D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[t("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"斜入射时，吸收体迎光侧挡光、背光侧少挡，等效孔径平移。反射式 EUV 还走双程几何，阴影更重。波导：开口宽度接近波长时，传播常数随宽度变，相位不是 \\(\\Delta n\\cdot t\\) 的简单光程。这会改干涉条件，于是最佳焦距变成图形相关——叠在镜头离焦和胶厚驻波之上，E–D 窗口的焦轴再被切一刀。",-1)),(e(),l(n,null,{default:E(()=>[o(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22EUV%20%E4%BB%A5%E7%BA%A6%206%20%E5%BA%A6%E6%96%9C%E5%85%A5%E5%B0%84%22%5D%20--%3E%20A1%5B%22%E4%B8%8B%E8%A1%8C%EF%BC%9A%E8%BF%8E%E5%85%89%E4%BE%A7%E5%90%B8%E6%94%B6%E4%BD%93%E6%8C%A1%E5%85%89%22%5D%0A%20%20A1%20--%3E%20R%5B%22%E5%A4%9A%E5%B1%82%E8%86%9C%E5%8F%8D%E5%B0%84%22%5D%0A%20%20R%20--%3E%20A2%5B%22%E4%B8%8A%E8%A1%8C%EF%BC%9A%E5%86%8D%E6%AC%A1%E7%A9%BF%E8%BF%87%E5%90%B8%E6%94%B6%E4%BD%93%E6%8A%95%E5%BD%B1%22%5D%0A%20%20A2%20--%3E%20S%5B%22%E9%98%B4%E5%BD%B1%E5%8A%A0%E6%B7%B1%E4%B8%94%E6%96%B9%E5%90%91%E5%9B%BA%E5%AE%9A%22%5D%0A%20%20S%20--%3E%20O%5B%22%E6%9C%89%E6%95%88%E5%BC%80%E5%8F%A3%E9%9A%8F%E6%96%B9%E4%BD%8D%E5%8F%98%E7%AA%84%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">这张图回答的问题是：EUV 为什么比透射式 DUV 阴影更重。光是斜着进来、反射后再斜着出去，吸收体的投影几何走了两遍，等效开口被削两次——这是反射式掩模独有的「双程」账。</span></p><p><span class="marginnote">直觉类比：窄开口像一条极窄的走廊，光进去后不是直线穿过，而是在两壁之间来回反弹着走。走廊越窄、越接近波长，反弹越多，走出去的相位和幅度就不再等于「折射率 × 厚度」这笔简单账，这就是波导效应。</span></p><p>偏振：线栅开口对 s/p 透过率不同，掩模本身就是弱偏振器。高 NA 矢量效应有一部分在掩模上就已经发生，不只在晶圆侧大夹角。</p><p>全芯片不能处处 FDTD，OPC / ILT 用域分解、边查找表或代理模型去逼近 3D 衍射级。校正环里必须调用这套代理，否则边缘放置误差在离轴方向系统性偏。减薄吸收体减阴影、付光学密度，在 EUV 上还改缺陷可检测性，是多层缺陷课的接口。</p><p><span class="marginnote">MEF 在 3D 模型里会变：小 SRAF 的实际透过不再等于面积比。ILT 曲边在 3D 下尤其不能用 Kirchhoff 签字。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开 LELE 套刻如何把两次阴影指纹叠在一起——多重图形课只在需要时引用「每次曝光自己的 M3D」。也不把掩模台倾斜的机械误差叫成 M3D。Pellicle 皱纹是另一层相位物。后课默认：低 \\(k_1\\) 的 OPC/SMO 以含 M3D 为默认，薄屏只作教学零阶。</p><p>High-NA EUV 掩模侧角度更大，阴影按方位更重，半场并不自动取消 M3D。那是 EXE 课的附件，本课只把机制钉在「厚度 + 斜入射」。DUV 浸没的主光线角小于 EUV，但 MoSi 厚度仍够把 HV 偏置做进 OPC 表。</p><p><span class="marginnote">最佳焦距随图形漂移时，E–D 重叠窗口在焦轴上被 M3D 再切一刀。看起来像 \\(k_2\\) 变差，根子在物体侧相位，不是镜头离焦公式改了。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>吸收体有厚度，薄屏 \\(t(x,y)\\) 是零阶，不是量产误差为零。</li><li>斜入射阴影造成 HV 偏置与类似平移的指纹。</li><li>开口波导改相位，最佳焦距随图形漂。</li><li>OPC 必须用厚掩模衍射级，不能只拧剂量。</li><li>下一课钉求解器切换；多次曝光换节距在多重图形课，每次仍带自己的 M3D。</li><li>出处：Mack / Levinson 对 EMF / thick-mask；Bakshi 与 ASML 对 EUV 掩模阴影的公开讨论。</li></ul>',11))])}const _=B(D,[["render",h]]);export{k as __pageData,_ as default};
